#!/usr/bin/env python3
"""SIGNATURE MIX: spec IDs + maker marks -> stamped registry."""
import hashlib, re

class Registry:
    def __init__(self):
        self.next = 1; self.items = {}
    def mint(self, title):
        sid = "JAH-SPEC-%06d" % self.next; self.next += 1
        code = "SIG-" + hashlib.sha256((sid+title).encode()).hexdigest()[:12].upper()
        self.items[sid] = {"title": title, "stamp": "(JAH) " + code}
        return sid

if __name__ == "__main__":
    r = Registry()
    a, b = r.mint("Planter"), r.mint("Sorter")
    print(r.items[a]); print(r.items[b])
    assert re.match(r"^JAH-SPEC-\d{6}$", a) and r.items[a]["stamp"].startswith("(JAH) SIG-")
    assert r.items[a]["stamp"] != r.items[b]["stamp"]
    print("OK: registry mints stamped IDs")

