#!/usr/bin/env python3
"""SIGNATURE MIX: validator + lineage -> archive tools."""
import re
class Lineage:
    def __init__(self): self.p={}
    def link(self,c,p,r): self.p[c]=(p,r)
    def walk(self,n):
        ch=[n]
        while n in self.p: n=ch.append(self.p[n][0]) or self.p[ch[-2]][0]
        return ch
def valid(rec):
    return bool(re.match(r"^JAH-[A-Z]+-\d+$",rec.get("id",""))) and rec.get("ladder_rank") in (1,2,3)

if __name__ == "__main__":
    recs=[{"id":"JAH-REC-000001","ladder_rank":1},{"id":"JAH-REC-000002","ladder_rank":2},
          {"id":"bad","ladder_rank":9}]
    good=[r for r in recs if valid(r)]
    lg=Lineage()
    lg.link(good[1]["id"],good[0]["id"],"version-of")
    chain=lg.walk(good[1]["id"])
    assert len(good)==2 and chain==["JAH-REC-000002","JAH-REC-000001"]
    print("OK: validated 2/3 records, lineage linked")

