#!/usr/bin/env python3
"""SIGNATURE MIX: spec IDs + lineage -> spec registry."""
class Registry:
    def __init__(self): self.n=1; self.titles={}; self.parent={}
    def mint(self,title,parent=None):
        sid="JAH-SPEC-%06d"%self.n; self.n+=1
        self.titles[sid]=title
        if parent: self.parent[sid]=parent
        return sid
    def lineage(self,sid):
        ch=[sid]
        while ch[-1] in self.parent: ch.append(self.parent[ch[-1]])
        return ch

if __name__ == "__main__":
    r=Registry()
    a=r.mint("Base planter"); b=r.mint("Planter v2",parent=a); c=r.mint("Planter Pro",parent=b)
    print(r.lineage(c))
    assert r.lineage(c)==[c,b,a] and r.titles[b]=="Planter v2"
    print("OK: registry with lineage")

