#!/usr/bin/env python3
"""SIGNATURE MIX: hangman + RPS -> arcade night."""
BEATS={"rock":"scissors","scissors":"paper","paper":"rock"}
def hangman(word,guesses):
    found={g for g in guesses if g in word}
    return set(word)<=found
def rps(p,c): return "tie" if p==c else ("win" if BEATS[p]==c else "lose")

if __name__ == "__main__":
    assert hangman("arcade",["a","r","c","d","e"])
    results={rps(p,c) for p in BEATS for c in BEATS}
    assert results=={"win","lose","tie"}
    score=sum(1 for p in ["rock","paper","scissors"] if rps(p,"scissors")=="win")
    assert score==1  # only rock beats scissors
    print("OK: arcade night — hangman won, RPS complete")

